    static object Resolve(ModelDoc2 part,string b64,out int state){state=-999;try{return part.Extension.GetObjectByPersistReference3(Convert.FromBase64String(b64),out state);}catch{return null;}}
    static Surface Surf(Face2 f){try{return f.IGetSurface();}catch{return null;}}
